import { templateAssetProjectionToValue } from './template-asset.model';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';

describe('templateAssetProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    template: { $ref: 'ref-template' },
    tenant: { $ref: 'ref-tenant' },
    code: 'value-code',
    type: 'value-type',
    content: 'value-content',
    enabled: 'value-enabled',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(templateAssetProjectionToValue(null)).toBeNull();
    expect(templateAssetProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(templateAssetProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      template: () => ({ uid: 'ref-template' }),
      tenant: () => ({ uid: 'ref-tenant' }),
      code: 'value-code',
      type: 'value-type',
      content: 'value-content',
      enabled: 'value-enabled',
      version: 'value-version',
    } as any;
    expect(templateAssetProjectionToValue(projection)).toEqual(value);
  });
});
